import {createWorld,presets,step,metrics,addObstacle,validate,WIDTH,HEIGHT} from "./model.js";
import {expose,tool,number,canvasPointer,clamp} from "./ui.js";
const $=s=>document.querySelector(s),canvas=$("#field"),ctx=canvas.getContext("2d");let seed=21,world=createWorld(160,seed),rules={...presets.school},mode="guide",pointer=null,running=!matchMedia("(prefers-reduced-motion: reduce)").matches,frame=0,last=0,accumulator=0,trail=true;
function sync(){for(const key of ["separation","alignment","cohesion","vision"]){$("#"+key).value=rules[key];$("#"+key+"-out").value=rules[key].toFixed(key==="vision"?0:1);}$("#size").value=world.boids.length;$("#size-out").value=String(world.boids.length);$("#seed").textContent=`SEED ${seed}`;$("#count").textContent=`${world.boids.length} AGENTS`;$("#mode-label").textContent={guide:"CURSOR / 모으기",avoid:"CURSOR / 피하기",obstacle:"CLICK / 장애물"}[mode];for(const b of document.querySelectorAll("[data-mode]"))b.setAttribute("aria-pressed",String(b.dataset.mode===mode));$("#play").textContent=running?"일시정지":"재생";updateMetrics();}
function updateMetrics(){const m=metrics(world);$("#order").textContent=`${Math.round(m.order*100)}%`;$("#speed").textContent=`${m.speed.toFixed(0)} px/s`;$("#obstacles").textContent=`${m.obstacles} / 12`;}
function draw(clear=false){
  ctx.fillStyle=!trail||clear?"#07141f":"rgba(7,20,31,.2)";ctx.fillRect(0,0,WIDTH,HEIGHT);
  if(!trail||clear){ctx.strokeStyle="#163445";ctx.lineWidth=.5;for(let x=0;x<WIDTH;x+=80){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,HEIGHT);ctx.stroke();}for(let y=0;y<HEIGHT;y+=80){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(WIDTH,y);ctx.stroke();}}
  for(const o of world.obstacles){ctx.fillStyle="#112c40";ctx.strokeStyle="#6389a0";ctx.lineWidth=2;ctx.beginPath();ctx.arc(o.x,o.y,o.r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle="#aecbdc";ctx.font="16px monospace";ctx.textAlign="center";ctx.fillText("×",o.x,o.y+6);}
  world.boids.forEach((b,i)=>{ctx.save();ctx.translate(b.x,b.y);ctx.rotate(Math.atan2(b.vy,b.vx));ctx.fillStyle=["#65f1da","#61bffc","#f1e68d"][i%3];ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=5;ctx.beginPath();ctx.moveTo(7,0);ctx.lineTo(-4,-3);ctx.lineTo(-2,0);ctx.lineTo(-4,3);ctx.closePath();ctx.fill();ctx.restore();});
  if(pointer){ctx.strokeStyle=pointer.mode==="avoid"?"#ffb596":"#9eeecf";ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(pointer.x,pointer.y,18,0,Math.PI*2);ctx.moveTo(pointer.x-26,pointer.y);ctx.lineTo(pointer.x+26,pointer.y);ctx.moveTo(pointer.x,pointer.y-26);ctx.lineTo(pointer.x,pointer.y+26);ctx.stroke();}
}
function tick(now){frame=0;if(!running)return;accumulator+=Math.min((now-(last||now))/1000,.08);last=now;let n=0;while(accumulator>=1/60&&n++<5){step(world,rules,1/60,pointer);accumulator-=1/60;}draw();updateMetrics();frame=requestAnimationFrame(tick);}
function setRunning(value){running=Boolean(value);if(frame)cancelAnimationFrame(frame);frame=0;last=0;accumulator=0;if(running)frame=requestAnimationFrame(tick);sync();}
function reset(count=world.boids.length){world=createWorld(count,++seed);pointer=null;draw(true);sync();}
function configure(input){const next={...rules};for(const key of ["separation","alignment","cohesion"])if(input[key]!==undefined)next[key]=number(input[key],0,3,key);if(input.vision!==undefined)next.vision=number(input.vision,30,130,"vision");validate(next);const count=input.count===undefined?world.boids.length:number(input.count,40,280,"count");if(!Number.isInteger(count))throw new RangeError("count must be integer");rules=next;if(count!==world.boids.length)reset(count);sync();if(!running)draw(true);return summary();}
function summary(){return {seed,running,rules:{...rules},...metrics(world)};}
for(const key of ["separation","alignment","cohesion","vision"])$("#"+key).addEventListener("input",event=>configure({[key]:Number(event.target.value)}));$("#size").addEventListener("input",event=>configure({count:Number(event.target.value)}));
for(const b of document.querySelectorAll("[data-preset]"))b.addEventListener("click",()=>{rules={...presets[b.dataset.preset]};sync();if(!running)draw(true);});for(const b of document.querySelectorAll("[data-mode]"))b.addEventListener("click",()=>{mode=b.dataset.mode;pointer=null;sync();if(!running)draw(true);});
$("#play").addEventListener("click",()=>setRunning(!running));$("#reset").addEventListener("click",()=>reset());$("#clear").addEventListener("click",()=>{world.obstacles=[];draw(true);sync();});$("#trail").addEventListener("change",event=>{trail=event.target.checked;draw(true);});
canvas.addEventListener("pointermove",event=>{if(mode==="obstacle")return;pointer={...canvasPointer(canvas,event),mode};if(!running)draw(true);});canvas.addEventListener("pointerleave",()=>{pointer=null;if(!running)draw(true);});canvas.addEventListener("pointerdown",event=>{const point=canvasPointer(canvas,event);if(mode==="obstacle"){try{addObstacle(world,point.x,point.y);$("#feedback").textContent="장애물을 놓았습니다. 무리가 우회하는 모습을 관찰하세요.";}catch(error){$("#feedback").textContent=error.message;}sync();draw(true);}else{pointer={...point,mode};if(!running)draw(true);}});
canvas.addEventListener("keydown",event=>{const moves={ArrowLeft:[-25,0],ArrowRight:[25,0],ArrowUp:[0,-25],ArrowDown:[0,25]};if(moves[event.key]){event.preventDefault();pointer??={x:WIDTH/2,y:HEIGHT/2,mode:mode==="avoid"?"avoid":"guide"};pointer.x=clamp(pointer.x+moves[event.key][0],0,WIDTH);pointer.y=clamp(pointer.y+moves[event.key][1],0,HEIGHT);draw(true);}else if(event.key==="Enter"&&mode==="obstacle"){event.preventDefault();try{addObstacle(world,pointer?.x??WIDTH/2,pointer?.y??HEIGHT/2);}catch(error){$("#feedback").textContent=error.message;}draw(true);sync();}});
document.addEventListener("visibilitychange",()=>{if(document.hidden)setRunning(false);});draw(true);sync();if(running)frame=requestAnimationFrame(tick);
expose([tool("read_swarm_state","Read flock rules and computed aggregate motion, without changing playback.",{},summary,true),tool("configure_swarm","Change bounded flock rules or count, using the same visible controls.",{count:{type:"integer",minimum:40,maximum:280},separation:{type:"number",minimum:0,maximum:3},alignment:{type:"number",minimum:0,maximum:3},cohesion:{type:"number",minimum:0,maximum:3},vision:{type:"number",minimum:30,maximum:130}},configure),tool("set_swarm_playback","Play or pause the flock animation.",{running:{type:"boolean"}},input=>{if(typeof input.running!=="boolean")throw new TypeError("running required");setRunning(input.running);return summary();})]);
